/** A01-MOVS500: registros fijos de 450 bytes con acceso por número relativo (ACTUAL KEY). */
@Component
public class Movs500Reader {

    private static final int LONGITUD = 450;

    /** SEEK A01-MOVS500 RECORD con ACTUAL KEY = apuntador + 1. */
    public Stream<MovimientoS500> desde(Path archivo, long ultimoProcesado) throws IOException {
        var ch = FileChannel.open(archivo, StandardOpenOption.READ);
        ch.position(ultimoProcesado * LONGITUD);              // registros base 1
        return StreamSupport.stream(new RegistroFijoSpliterator(ch, LONGITUD), false)
                .map(MovimientoS500::parse)
                .onClose(() -> cerrar(ch));
    }
}

@Component
@RequiredArgsConstructor
public class LectorMovs500 {

    private final ApuntadorRepository apuntadores;
    private final Movs500Reader reader;
    private final GeneradorAlertas generador;      // 030341-VALIDA-PC
    private final Cancelaciones cancelaciones;     // 030390-CANCELA
    private final LimitesEnvio limites;
    private final P014Properties props;

    public void procesarPendientes() {
        var ap = apuntadores.findById(props.movs500()).orElseThrow();   // 030320-LEE-CONTROL
        long procesados = ap.getUltimoRegistro();
        var envios = new AtomicInteger();                                // WKS-NUM-ENVIOS

        try (var movs = reader.desde(Path.of(props.movs500()), procesados)) {
            for (var it = movs.iterator(); it.hasNext(); ) {
                MovimientoS500 m = it.next();
                if (m.funcion() == 99 || envios.get() > limites.envios()) break;  // 030342
                procesados++;                                   // ADD 1 TO W77-AUT-ENVIO500

                if (m.tipoProceso() > 39 && m.tipoProceso() < 44) continue;     // filtro Teletón
                if (m.funcion() == 21 || m.funcion() == 22) {
                    cancelaciones.aplicar(m);
                    break;              // una cancelación cierra el recorrido de este ciclo
                }
                generador.procesar(m, envios);                 // ocurrencias 1..5
            }
        }
        ap.avanzarA(procesados);
        apuntadores.save(ap);                                 // 030350-ACTUALIZA-CONTROL
    }
}

@Service
@RequiredArgsConstructor
class ApuntadorService {

    private final ApuntadorRepository repo;

    /**
     * 030350-ACTUALIZA-CONTROL. El fuente hace REWRITE ... INVALID KEY NEXT SENTENCE:
     * si la escritura falla, sigue sin aviso. Aquí un fallo se propaga.
     */
    @Transactional
    public void grabar(String archivo, long ultimoProcesado) {
        var ap = repo.findById(archivo)
                .orElseThrow(() -> new IllegalStateException("Sin registro de control para " + archivo));
        ap.avanzarA(ultimoProcesado);
        // OptimisticLockException si otra instancia movió el apuntador: se aborta el ciclo
    }
}

@Component
@RequiredArgsConstructor
public class GeneradorAlertas {

    private final CatalogoProteccionCobros catalogo;   // CVETRAN-PC OCCURS 10000
    private final AlertaService alertas;
    private final LimitesEnvio limites;

    public void procesar(MovimientoS500 m, AtomicInteger envios) {
        for (int occ = 1; occ <= 5; occ++) {
            int clave = m.claveTransaccion(occ);
            if (clave == 0) break;                          // MOVE 6 TO WKS-NUM-OCCURS / EXIT PERFORM
            if (m.funcion() == 2) { alertas.actualizaEliminacion(m, occ); continue; }  // 010700-CICLO-ACT
            if (m.funcion() != 1) continue;

            catalogo.marca(clave).ifPresent(marca -> {
                if (marca.servicio1()) alertas.altaServicio1(m, occ, marca, envios);
                boolean origenValido = m.origen() == 1 || m.origen() == 3;
                boolean servicioAplica = m.servicioAlerta() == 2
                        || limites.alertasClienteNoContratado();
                if (marca.servicio2() && origenValido && servicioAplica)
                    alertas.altaServicio2(m, occ, envios);
            });
        }
    }
}

/** El catálogo se indexa por número de clave; un Map evita el límite de 10000 posiciones. */
@Component
class CatalogoProteccionCobros {
    private volatile Map<Integer, MarcaPc> marcas = Map.of();
    Optional<MarcaPc> marca(int clave) { return Optional.ofNullable(marcas.get(clave)); }
}

@Service
@RequiredArgsConstructor
public class AlertaService {

    private final AlertaRepository repo;              // S151B07PROTCOB
    private final VentanaServicio ventana;
    private final MensajeriaAlertas mensajeria;       // 060100 / 060200 + SEND COMS-OUT
    private final OperadorModo modo;                  // W88-HI-13: forzar servicio fuera de horario

    /** 030500-ALTA-SERV1. */
    public void altaServicio1(MovimientoS500 m, int occ, MarcaPc marca, AtomicInteger envios) {
        envios.incrementAndGet();
        boolean enHorario = modo.forzado() || ventana.abierta(LocalTime.now());
        boolean diaPermite = ventana.diaHabil() || marca.enviaEnDiaInhabil();   // ENVDHBL = 2

        if (enHorario && diaPermite) {
            var alerta = AlertaProteccionCobro.desde(m, occ, 1, EstatusAlerta.ENVIADA);
            if (guardar(alerta)) mensajeria.enviar(alerta);   // WKS-DUPLICADO = 0
        } else {
            guardar(AlertaProteccionCobro.desde(m, occ, 1, EstatusAlerta.PENDIENTE)
                    .conEnvios(0));                            // 0030550-GUARD-PEN-ALT
        }
    }

    /** BEGIN-TRANSACTION / STORE / END-TRANSACTION. Devuelve false si ya existía. */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    boolean guardar(AlertaProteccionCobro a) {
        try {
            repo.saveAndFlush(a);
            return true;
        } catch (DataIntegrityViolationException dup) {
            log.info("REG DUPLICADO {} {} {} {}", a.getContrato(), a.getAutPc(), a.getAutS151(), a.getOcurrencia());
            return false;
        }
    }
}

