    claves-excluidas: [526, 527, 532, 534, 571, 579, 2017, 2020, 2103, 2105,
                       2115, 2131, 2141, 2268, 2334, 2336]          # W88-CLAVES-EXCLUIDAS
    exclusion-puntual: { clave: 1015, sucursal: 342, caja: 68 }

// ---------------------------------------------------------------------------
    /** 030500-ALTA-SERV2. */
    public void altaServicio2(MovimientoS500 m, int occ, AtomicInteger envios) {
        int clave = m.claveTransaccion(occ);
        if (props.servicio2().excluye(clave, m.sucursalInicial(), m.cajaInicial())) return;

        envios.incrementAndGet();
        int indServ = (m.servicioAlerta() == 2) ? 2 : 3;     // 060150-VALIDA-IND-SERV
        var alerta = AlertaProteccionCobro.desde(m, occ, indServ, EstatusAlerta.ENVIADA)
                .conAutPc(m.servicioAlerta())                // B07-AUT-PC = servicio de alerta
                .conDatosGenerales(DatosServicio2.de(m));    // 030400-DATGEN-SERV2
        if (!modo.envioAlertasActivo()) alerta = alerta.conEstatus(EstatusAlerta.PENDIENTE).conEnvios(0);

        if (guardar(alerta) && modo.envioAlertasActivo()) mensajeria.enviarServicio2(alerta);
    }

